SELECT SQL_SEQ, PGM_NM, SQL_NM, SQL_DESC, USE_YN,
       CREATE_DATE, CREATED_BY, UPDATE_DATE, UPDATED_BY
FROM SY_SQL_MASTER
WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

    AND (
        SQL_NM LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR
        SQL_DESC LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%'
    )


    AND PGM_NM = #{pgmNm, jdbcType=VARCHAR}

ORDER BY TO_NUMBER(SQL_SEQ) DESC

